    pub fn name(&self) -> &'static str {
        Self::tag_name(self.tag()).unwrap_or("?")
    }

    pub fn tag_name(tag: u16) -> Option<&'static str> {
        COMMAND_VARIANTS.iter().find(|v| v.0 == tag).map(|v| v.1)
    }

    /// Encodes one record into `out`, replacing what it held.
    pub fn encode(&self, out: &mut Vec<u8>) -> Result<(), TooLarge> {
        let mut w = Writer::reuse(out);
        w.u16(self.tag());
        w.u16(0);
        let result = self.put_fields(&mut w);
        *out = w.finish();
        result?;
        if out.len() > MAX_RECORD {
            debug_assert!(false, "{} exceeded MAX_RECORD despite its bounds", self.name());
            return Err(TooLarge { field: "record", len: out.len(), max: MAX_RECORD });
        }
        Ok(())
    }

